#include "frontier.h"
#include "standard.h"

#include "memory.h"
#include "strings.h"
#include "lang.h"
#include "langinternal.h"
#include "tablestructure.h"

/* Token enum for all verbs in the semaphore processor */
enum {
    semv_lock = 0,
    semv_unlock = 1
};

/* Forward declarations from langverbs.c */
extern boolean locksemaphoreverb(hdltreenode hparam1, tyvaluerecord *vreturned);
extern boolean unlocksemaphoreverb(hdltreenode hparam1, tyvaluerecord *vreturned);

static boolean semaphore_valueproc(short token, hdltreenode hparam1,
                                     tyvaluerecord *vreturned,
                                     bigstring bserror) {
    #pragma unused(bserror)

    switch(token) {
        case semv_lock:
            /* @IMPLEMENTED semaphore.lock - Forwards to locksemaphoreverb */
            return locksemaphoreverb(hparam1, vreturned);

        case semv_unlock:
            /* @IMPLEMENTED semaphore.unlock - Forwards to unlocksemaphoreverb */
            return unlocksemaphoreverb(hparam1, vreturned);

        default:
            return false;
    }
}

boolean semaphoreinitverbs(void) {
    hdlhashtable htable = nil;
    bigstring bsname;

    copystring(BIGSTRING("\psemaphore"), bsname);

    if (!newfunctionprocessor(bsname, &semaphore_valueproc, false, &htable))
        return false;

    pushhashtable(htable);

    #define ADD_VERB(name, tok) do { \
        bigstring bs; \
        copystring(name, bs); \
        if (!langaddkeyword(bs, tok)) { \
            pophashtable(); \
            return false; \
        } \
    } while(0)

    ADD_VERB(BIGSTRING("\plock"), semv_lock);
    ADD_VERB(BIGSTRING("\punlock"), semv_unlock);

    #undef ADD_VERB

    pophashtable();
    return true;
}
